'use strict';
const $=id=>document.getElementById(id),MAX=8,feeds=[];const csrf=<?php echo json_encode($_SESSION['csrf']); ?>,cameraConfig=<?php echo json_encode($CAMERA_LOCATION); ?>;
let selected=0,model=null,alertCount=0,roundRobin=0,lastTick=0,cameraPending=false;
function makeFeed(){const index=feeds.length,card=document.createElement('section');card.className='feed';card.tabIndex=0;card.setAttribute('aria-label','Canal '+(index+1));card.innerHTML=`<div class="feed-top"><span>● CANAL ${String(index+1).padStart(2,'0')}</span><span class="source">SIN FUENTE</span></div><div class="viewer"><div class="empty">SIN SEÑAL<small>Carga un video o activa la cámara</small></div><video playsinline muted></video><canvas></canvas><div class="alarm" hidden>⚠ POSIBLE ACCIDENTE</div></div><div class="feed-bottom"><span class="badge">EN ESPERA</span><span class="info">Sin análisis</span></div>`;$('grid').append(card);const video=card.querySelector('video'),overlay=card.querySelector('canvas'),sample=document.createElement('canvas'),aiSample=document.createElement('canvas');const f={index,card,video,overlay,ctx:overlay.getContext('2d'),sample,sc:sample.getContext('2d',{willReadFrequently:true}),aiSample,asc:aiSample.getContext('2d'),name:'',type:'',url:null,stream:null,version:0,session:'',geo:null,previous:null,lastTime:-1,motion:[],vehicles:[],aiAt:-Infinity,vehicleTracks:[],pairs:new Map(),seenPairs:new Set(),vehicleId:1,inferenceTime:null,alertBox:null,alertUntil:0,cooldown:0};feeds.push(f);
card.onclick=()=>selectFeed(index);card.onkeydown=e=>{if(e.key==='Enter'){selectFeed(index);e.preventDefault();}if(e.code==='Space'){e.preventDefault();selectFeed(index);togglePlay(f);}};card.ondblclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else card.requestFullscreen().catch(()=>{});};
video.onloadedmetadata=()=>{overlay.width=320;overlay.height=Math.max(1,Math.round(320*video.videoHeight/video.videoWidth));sample.width=overlay.width;sample.height=overlay.height;card.querySelector('.empty').hidden=true;fit(f);};
video.onseeking=()=>resetAnalysis(f);video.onended=()=>{resetAnalysis(f);card.querySelector('.badge').textContent='FINALIZADO';card.querySelector('.info').textContent='Espacio para repetir';};video.onpause=()=>{f.motion=[];f.ctx.clearRect(0,0,overlay.width,overlay.height);};video.onerror=()=>{resetAnalysis(f);card.querySelector('.badge').textContent='VIDEO NO COMPATIBLE';card.querySelector('.info').textContent='Prueba un MP4';};new ResizeObserver(()=>fit(f)).observe(card.querySelector('.viewer'));return f;}
function selectFeed(index){selected=index;feeds.forEach((f,i)=>f.card.classList.toggle('selected',i===index));}
function fit(f){if(!f.video.videoWidth)return;const r=f.video.getBoundingClientRect(),scale=Math.min(r.width/f.video.videoWidth,r.height/f.video.videoHeight);f.overlay.style.width=f.video.videoWidth*scale+'px';f.overlay.style.height=f.video.videoHeight*scale+'px';}
function resetAnalysis(f){f.version++;f.previous=null;f.lastTime=-1;f.motion=[];f.vehicles=[];f.aiAt=-Infinity;f.vehicleTracks=[];f.pairs.clear();f.inferenceTime=null;f.alertBox=null;f.alertUntil=0;f.card.classList.remove('alert');f.card.querySelector('.alarm').hidden=true;f.ctx.clearRect(0,0,f.overlay.width,f.overlay.height);}
function release(f){resetAnalysis(f);if(f.stream)f.stream.getTracks().forEach(t=>t.stop());f.stream=null;f.video.pause();f.video.srcObject=null;f.video.removeAttribute('src');f.video.load();if(f.url)URL.revokeObjectURL(f.url);f.url=null;f.type='';f.name='';f.geo=null;f.seenPairs.clear();f.session=crypto.randomUUID();f.card.querySelector('.empty').hidden=false;}
function slot(){let f=feeds.find(f=>!f.type);if(!f&&feeds.length<MAX)f=makeFeed();return f;}
async function play(f){try{await f.video.play();}catch(e){f.card.querySelector('.badge').textContent='PAUSADO';f.card.querySelector('.info').textContent='Selecciona el canal y pulsa Espacio';}}
async function togglePlay(f){if(!f.type)return;if(f.video.paused){if(f.video.ended)f.video.currentTime=0;resetAnalysis(f);await play(f);}else{f.video.pause();resetAnalysis(f);f.card.querySelector('.badge').textContent='PAUSADO';}}
$('files').onchange=async()=>{const files=Array.from($('files').files);$('files').value='';let loaded=0;const jobs=[];for(const file of files){const f=slot();if(!f)break;release(f);f.type='file';f.name=file.name;f.url=URL.createObjectURL(file);f.video.src=f.url;f.card.querySelector('.source').textContent=file.name;f.card.querySelector('.badge').textContent='CARGANDO';jobs.push(play(f));loaded++;}selectFeed(selected);$('grid').classList.toggle('many',feeds.length>4);$('message').textContent=loaded===files.length?loaded+' video(s) cargado(s). Se analizan por separado.':loaded+' cargado(s); límite de 8 canales. Para reemplazar, selecciona un canal y arrastra el video sobre él.';await Promise.allSettled(jobs);};
// Arrastrar un archivo permite reemplazar un canal sin afectar a los demás.
function enableDrop(f){f.card.ondragover=e=>e.preventDefault();f.card.ondrop=async e=>{e.preventDefault();const file=e.dataTransfer.files[0];if(!file||!file.type.startsWith('video/'))return;release(f);f.type='file';f.name=file.name;f.url=URL.createObjectURL(file);f.video.src=f.url;f.card.querySelector('.source').textContent=file.name;selectFeed(f.index);await play(f);};}
$('camera').onclick=async()=>{if(cameraPending)return;cameraPending=true;$('camera').disabled=true;const f=feeds[selected].type?(slot()||feeds[selected]):feeds[selected];if(!f){$('message').textContent='Los 8 canales están ocupados.';cameraPending=false;$('camera').disabled=false;return;}release(f);f.type='camera';const version=f.version;f.name='Cámara local';f.card.querySelector('.source').textContent=f.name;selectFeed(f.index);try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Abre en localhost o HTTPS para usar la cámara.');const incoming=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:false});if(f.version!==version){incoming.getTracks().forEach(t=>t.stop());return;}f.stream=incoming;f.video.srcObject=incoming;await play(f);$('message').textContent='Cámara activa en canal '+(f.index+1);if(!cameraConfig.label&&navigator.geolocation)navigator.geolocation.getCurrentPosition(p=>{if(f.type==='camera'&&f.stream===incoming)f.geo={lat:p.coords.latitude,lon:p.coords.longitude,accuracy:p.coords.accuracy};},()=>{},{timeout:10000,maximumAge:0});}catch(e){release(f);f.card.querySelector('.source').textContent='SIN FUENTE';$('message').textContent='No se pudo activar la cámara: '+e.message;}finally{cameraPending=false;$('camera').disabled=false;}};
function detect(data,prev,w,h,sensitivity,minArea){const block=8,cols=Math.ceil(w/block),rows=Math.ceil(h/block),mask=new Uint8Array(cols*rows);let global=0;for(let i=0;i<w*h;i++)global+=data[i]-prev[i];global/=w*h;const threshold=8+(100-sensitivity)*.55;
for(let by=0;by<rows;by++)for(let bx=0;bx<cols;bx++){let changed=0,total=0;for(let y=by*block;y<Math.min(h,(by+1)*block);y++)for(let x=bx*block;x<Math.min(w,(bx+1)*block);x++){const i=y*w+x;if(Math.abs(data[i]-prev[i]-global)>threshold)changed++;total++;}if(changed/total>.18)mask[by*cols+bx]=1;}
// Dilatación para unir zonas cercanas de un mismo movimiento.
const expanded=mask.slice();for(let i=0;i<mask.length;i++)if(mask[i]){const x=i%cols,y=Math.floor(i/cols);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const nx=x+dx,ny=y+dy;if(nx>=0&&ny>=0&&nx<cols&&ny<rows)expanded[ny*cols+nx]=1;}}
const boxes=[];for(let i=0;i<expanded.length;i++){if(!expanded[i])continue;const queue=[i];expanded[i]=0;let n=0,x0=cols,y0=rows,x1=0,y1=0;for(let q=0;q<queue.length;q++){const k=queue[q],x=k%cols,y=Math.floor(k/cols);n+=mask[k];x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y);for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,j=ny*cols+nx;if(nx>=0&&ny>=0&&nx<cols&&ny<rows&&expanded[j]){expanded[j]=0;queue.push(j);}}}if(n>=minArea)boxes.push({x:x0*block,y:y0*block,w:Math.min(w,(x1+1)*block)-x0*block,h:Math.min(h,(y1+1)*block)-y0*block});}return boxes;}
function center(b){return {x:b.x+b.w/2,y:b.y+b.h/2};}
function overlap(a,b){const iw=Math.max(0,Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x)),ih=Math.max(0,Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y));return iw*ih/Math.min(a.w*a.h,b.w*b.h);}
function trackVehicles(f,boxes,t){
 const dt=f.inferenceTime===null?0:t-f.inferenceTime;f.inferenceTime=t;
 if(dt<=0||dt>2){f.vehicleTracks=[];f.pairs.clear();}
 const old=f.vehicleTracks,used=new Set();
 f.vehicleTracks=boxes.map(b=>{const c=center(b);let match=null,cost=Infinity;for(const a of old){if(used.has(a.id))continue;const d=Math.hypot(c.x-a.x-a.vx*dt,c.y-a.y-a.vy*dt);if(d<cost&&d<Math.max(25,Math.max(b.w,b.h)*.6)){cost=d;match=a;}}if(!match)return {...c,b,id:f.vehicleId++,vx:0,vy:0,age:1};used.add(match.id);return {...c,b,id:match.id,vx:match.vx*.35+(c.x-match.x)/dt*.65,vy:match.vy*.35+(c.y-match.y)/dt*.65,age:match.age+1};});
 let hit=null;const current=new Set();for(let i=0;i<f.vehicleTracks.length;i++)for(let j=i+1;j<f.vehicleTracks.length;j++){
 const a=f.vehicleTracks[i],b=f.vehicleTracks[j],key=[a.id,b.id].sort((x,y)=>x-y).join(':'),dist=Math.hypot(a.x-b.x,a.y-b.y),contact=overlap(a.b,b.b),prev=f.pairs.get(key);current.add(key);
 const closing=prev&&dt>0?(prev.dist-dist)/dt:0,relative=Math.hypot(a.vx-b.vx,a.vy-b.vy),limit=6;
 const approaching=closing>limit*.3?t:(prev?.approachTime??-Infinity);const recentApproach=t-approaching<1.5;
 // Dos observaciones de contacto, precedidas de aproximación. Sin temporizadores ligados al clip.
 const touching=contact>.12,streak=touching&&recentApproach?(prev?.streak||0)+1:0;const duration=touching&&recentApproach?(prev?.duration||0)+dt:0;
 const change=prev?Math.abs(relative-prev.relative):0;
 const peak=Math.max(relative,prev?.peak||0);const drop=peak>limit&&relative<peak*.7;const directionChange=prev&&Math.hypot((a.vx-b.vx)-prev.rvx,(a.vy-b.vy)-prev.rvy)>limit*.75;
 if(streak>=3&&duration>=.18&&(drop||directionChange)&&a.age>=4&&b.age>=4&&!f.seenPairs.has(key)){const x=Math.min(a.b.x,b.b.x),y=Math.min(a.b.y,b.b.y);hit={key,x,y,w:Math.max(a.b.x+a.b.w,b.b.x+b.b.w)-x,h:Math.max(a.b.y+a.b.h,b.b.y+b.b.h)-y};}
 f.pairs.set(key,{dist,relative,streak,duration,approachTime:approaching,peak,rvx:a.vx-b.vx,rvy:a.vy-b.vy});
 }for(const key of f.pairs.keys())if(!current.has(key))f.pairs.delete(key);return hit;
}

function render(f){const c=f.ctx,w=f.overlay.width,h=f.overlay.height,t=f.video.currentTime;c.clearRect(0,0,w,h);c.lineWidth=1.5;c.font='9px monospace';c.strokeStyle='#46ff8a';for(const b of f.motion)c.strokeRect(b.x,b.y,b.w,b.h);if(t-f.aiAt<2){c.strokeStyle=c.fillStyle='#65b6ff';for(const a of f.vehicleTracks){const b=a.b;c.strokeRect(b.x,b.y,b.w,b.h);c.fillText('VEHÍCULO '+a.id,b.x,Math.max(10,b.y-3));c.beginPath();c.arc(a.x,a.y,2,0,Math.PI*2);c.fill();}}const active=f.alertBox&&t<f.alertUntil;f.card.classList.toggle('alert',!!active);f.card.querySelector('.alarm').hidden=!active;if(active){const b=f.alertBox;c.strokeStyle='#ff3358';c.lineWidth=3;c.strokeRect(b.x,b.y,b.w,b.h);}
f.card.querySelector('.badge').textContent=active?'POSIBLE ACCIDENTE':f.motion.length?'MOVIMIENTO':'SIN MOVIMIENTO';f.card.querySelector('.badge').className='badge '+(active?'red':f.motion.length?'motion':'');f.card.querySelector('.info').textContent=t.toFixed(1)+' s · '+f.motion.length+' zona(s)';}
function motionTick(now){requestAnimationFrame(motionTick);if(now-lastTick<100)return;lastTick=now;for(const f of feeds){const v=f.video;if(!f.type||v.paused||v.ended||v.seeking||v.readyState<2||!v.videoWidth||v.currentTime===f.lastTime)continue;const t=v.currentTime,w=f.sample.width,h=f.sample.height;try{f.sc.drawImage(v,0,0,w,h);const px=f.sc.getImageData(0,0,w,h).data,gray=new Uint8Array(w*h);let delta=0;for(let i=0;i<gray.length;i++){gray[i]=(px[i*4]+px[i*4+1]+px[i*4+2])/3;if(f.previous&&f.previous.length===gray.length)delta+=Math.abs(gray[i]-f.previous[i]);}const sceneCut=f.previous&&delta/gray.length>40;if(sceneCut){resetAnalysis(f);f.motion=[];}else f.motion=f.previous?detect(gray,f.previous,w,h,70,6):[];f.previous=gray;f.lastTime=t;render(f);}catch(e){f.card.querySelector('.badge').textContent='ERROR DE ANÁLISIS';f.card.querySelector('.info').textContent=e.message;}}
$('active').textContent=feeds.filter(f=>f.type&&!f.video.ended).length+' / '+MAX;$('moving').textContent=feeds.filter(f=>f.motion.length&&!f.video.paused).length;}
async function recognizeOne(){try{const eligible=feeds.filter(f=>f.type&&!f.video.paused&&!f.video.ended&&!f.video.seeking&&f.video.readyState>=2);if(!model||!eligible.length)return;const f=eligible[roundRobin++%eligible.length],t=f.video.currentTime,version=f.version;if(t===f.aiAt)return;f.aiSample.width=640;f.aiSample.height=Math.round(640*f.video.videoHeight/f.video.videoWidth);f.asc.drawImage(f.video,0,0,f.aiSample.width,f.aiSample.height);const predictions=await model.detect(f.aiSample,30,.45);if(f.version!==version||f.video.paused||f.video.seeking||Math.abs(f.video.currentTime-t)>2)return;const boxes=predictions.filter(p=>['car','bus','truck','motorcycle'].includes(p.class)).map(p=>({x:p.bbox[0]/2,y:p.bbox[1]/2,w:p.bbox[2]/2,h:p.bbox[3]/2,score:p.score}));f.vehicles=boxes;f.aiAt=t;const hit=trackVehicles(f,boxes,t);if(hit&&t>=f.cooldown){f.seenPairs.add(hit.key);f.alertBox=hit;f.alertUntil=t+6;f.cooldown=t+6;alertCount++;$('alerts').textContent=alertCount;saveEvent(f,hit,t);}}catch(e){$('modelStatus').textContent='Movimiento activo · Error del reconocimiento: '+e.message;}finally{setTimeout(recognizeOne,30);}}
function loadScript(src){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(Error('No se pudo descargar '+src));document.head.append(s);});}
async function initAI(){try{await loadScript('https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@4.22.0/dist/tf.min.js');await loadScript('https://cdn.jsdelivr.net/npm/@tensorflow-models/coco-ssd@2.2.3/dist/coco-ssd.min.js');model=await cocoSsd.load({base:'mobilenet_v2'});$('modelStatus').textContent='Movimiento activo en todos los canales · Reconocimiento vehicular por turnos listo';recognizeOne();}catch(e){$('modelStatus').textContent='Movimiento activo · IA no disponible; revisa Internet. Las alertas de accidente requieren la IA.';}}
function cell(row,value){const td=document.createElement('td');td.textContent=value;row.append(td);}
async function refreshEvents(){try{const r=await fetch('?api=list',{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error);$('eventRows').replaceChildren();for(const e of d.events){const tr=document.createElement('tr');cell(tr,e.detected_at);cell(tr,e.source_name);cell(tr,Number(e.video_second).toFixed(2)+' s');cell(tr,e.place+(e.latitude!==null?' · '+Number(e.latitude).toFixed(5)+', '+Number(e.longitude).toFixed(5):''));cell(tr,'Pendiente de revisión');$('eventRows').append(tr);}$('dbStatus').textContent='Conectado';}catch(e){$('dbStatus').textContent=e.message;}}
async function saveEvent(f,hit,t){const camera=f.type==='camera',place=camera?(cameraConfig.label||(f.geo?'Ubicación del dispositivo (verificar cámara)':'Ubicación no disponible')):'Lugar del video no especificado',body={csrf,event_id:f.session+':'+hit.key,source_type:f.type,source_name:'Canal '+(f.index+1)+' · '+f.name,video_second:t,place,latitude:camera?(cameraConfig.lat??f.geo?.lat??null):null,longitude:camera?(cameraConfig.lon??f.geo?.lon??null):null,accuracy:camera?(f.geo?.accuracy??null):null,box:hit};$('dbStatus').textContent='Guardando…';let err;for(let i=0;i<3;i++){try{const r=await fetch('?api=save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw Error(d.error);await refreshEvents();return;}catch(e){err=e;}}$('dbStatus').textContent='NO GUARDADO: '+err.message;}
for(let i=0;i<4;i++)makeFeed();selectFeed(0);feeds.forEach(enableDrop);
// Los canales añadidos también admiten reemplazar su video con arrastrar y soltar.
const originalMakeFeed=makeFeed;makeFeed=function(){const f=originalMakeFeed();enableDrop(f);return f;};
function clock(){$('clock').textContent=new Date().toLocaleString('es-MX',{timeZone:'America/Mexico_City'});}clock();setInterval(clock,1000);refreshEvents();requestAnimationFrame(motionTick);initAI();window.addEventListener('beforeunload',()=>feeds.forEach(release));
</script></body></html>